insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('ai-agent-app', 'payments', 'stripe', false);
insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('ai-agent-app', 'email', 'resend', false);
