insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('marketplace', 'payments', 'stripe-connect', false);
insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('marketplace', 'email', 'resend', false);
