insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('mobile-subscription-app', 'auth', 'supabase-auth', false);
insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('mobile-subscription-app', 'payments', 'revenuecat', false);
insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('mobile-subscription-app', 'email', 'resend', true);
insert into recipe_tools (recipe_slug, category, tool_slug, optional) values ('mobile-subscription-app', 'push', 'expo-push', true);
